import {supplyDebatePending,supplyDebateChoices,supplyDebateBlocked,canEscortSupplyStudent} from './supply-debate.js';
const debateEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function supplyDebatePanel(state,busy=false){
 const b=state.combatTrial,e=b?.supplyDebate;if(!e||!supplyDebatePending(b))return '';
 return `<section class="supply-debate" aria-live="polite" aria-label="구조 요청을 두고 나누는 파티 대화"><span>보급 도중 · 서로 다른 판단</span><h2>진열대 너머의 목소리</h2><p>“안쪽에 사람이 있어요. 혼자 나가기가 어려워요.” 창고 쪽에서 작은 목소리가 들린다.${e.previousMark?' 전에 위치를 기록해 둔 곳이다. 다시 요청을 확인한 지금, 동료들과 계획을 정한다.':''}</p><p class="debate-context">휴대 음식 ${e.context.food}개 · 생수 ${e.context.water}개 · 원정 인원 ${e.context.size}명 · 부상자 ${e.context.wounded}명 · 현재 적 ${e.context.enemies}마리</p><div class="debate-opinions">${e.opinions.map(o=>`<article data-supply-opinion="${o.key}" data-stance="${o.stance}"><strong>${debateEsc(o.name)}</strong><p>“${debateEsc(o.line)}”</p></article>`).join('')}</div><div class="debate-choices">${Object.entries(supplyDebateChoices).map(([id,c])=>{const blocked=supplyDebateBlocked(state,id);return `<button data-action="combatSupplyDecision" data-value="${id}" ${busy||blocked?'disabled':''}><strong>${c.label}</strong><small>${c.cost}</small>${blocked?`<small>${debateEsc(blocked)}</small>`:''}</button>`;}).join('')}</div><small>읽고 결정하는 동안 전투 턴은 흐르지 않아요. 구조를 택하면 학생에게 접근하고 함께 탈출해야 합니다.</small></section>`;
}
export function supplyStudentPanel(b,a,ready){const e=b.supplyDebate;if(!e||e.choice!=='rescue')return '';return `<section class="supply-student-action"><p>${e.rescued?'학생이 일행을 따라오고 있어요. 파티 전원이 탈출하면 구조가 확정됩니다.':'안쪽 학생 옆에서 동행을 도와야 해요. 결정만으로 구조가 완료되지는 않습니다.'}</p><button data-action="combatLocateSupplyStudent">학생 위치 보기</button><button data-action="combatSupplyRescue" ${!ready||!canEscortSupplyStudent(b,a)?'disabled':''}>${e.rescued?'학생 동행 중':'창고 학생 동행 돕기 · 행동력 1 / 스태미나 8'}</button></section>`;}
export function supplyDebriefPanel(state){
 const r=state.survivalRun;if(!r||r.activeSortie)return '';const records=(r.supplyStories?.records??[]).slice(-3).reverse();if(!records.length)return '';
 return `<section class="supply-debrief"><h2>돌아온 뒤, 동료들의 이야기</h2>${records.map(e=>`<article data-supply-record="${e.id}"><span>사태 ${e.day}일차 · ${e.site==='kiosk'?'매점':'편의점'} 구조 요청</span><h3>${e.rescued?'학생과 함께 돌아왔다':e.choice==='mark'?'물을 남기고 위치를 기록했다':e.choice==='rescue'?'구조를 시도했지만 함께 복귀를 확인하지 못했다':'파티의 귀환을 먼저 택했다'}</h3><p>${debateEsc(e.reason??'결정을 마치기 전에 원정을 중단했다.')}${e.keptPromise?' 전에 준비해서 돌아오자던 약속을 이번에 지켰다.':''}</p>${e.reactions.map(o=>`<blockquote><strong>${debateEsc(o.name)}</strong><p>“${debateEsc(o.line)}”</p></blockquote>`).join('')}${e.debrief?`<p class="debate-discussed">${e.debrief==='listen'?'동료들의 걱정과 다음 원정의 기준을 함께 들었다.':'선택한 이유와 실제 결과를 함께 짚었다.'}</p>`:`<div>${[['listen','아까 뭐가 제일 걱정됐어?'],['explain','내가 왜 그랬는지 얘기할게.']].map(([id,label])=>`<button data-action="survivalSupplyDebrief" data-value="${e.id}|${id}" ${r.status!=='active'?'disabled':''}>${label}</button>`).join('')}</div>`}</article>`).join('')}</section>`;
}
